// SPDX-License-Identifier: GPL-2.0-or-later
// Self-checking tb for rtl/generic/compression/lz4_decoder.v.
//
// Test vectors are REAL LZ4 block-format streams generated by python-lz4 (both
// 'high_compression' == LZ4_compress_HC and 'default'/acceleration=1 ==
// LZ4_compress_default modes, matching exactly what GroovyMAME's drawnogpu.cpp
// nogpu_blit() emits - see src/osd/modules/render/drawnogpu.cpp:902-905 in the
// groovymame source tree). Vectors + expected plaintext are hex files dumped to
// the scratchpad by tools/gen_lz4_test_vectors.py; $readmemh loads them here so
// this tb proves byte-exact decode against a real, independent LZ4 implementation
// - not just our own encoder round-tripping with itself.
`timescale 1ns/1ps
module lz4_decoder_tb;
    localparam VDIR = "/tmp/claude-1000/-home-subs-git-Groovy-TaNGer/351c4152-8b29-4980-9342-4daf7c2ebe12/scratchpad/";

    reg clk = 0; always #5 clk = ~clk;
    reg         rst;
    reg  [31:0] c_size;
    reg         in_valid;
    reg  [7:0]  in_data;
    wire        in_ready, out_valid, done;
    wire [7:0]  out_data;

    lz4_decoder #(.WINDOW_LOG(13)) dut (
        .clk(clk), .rst(rst), .c_size(c_size),
        .in_valid(in_valid), .in_data(in_data), .in_ready(in_ready),
        .out_valid(out_valid), .out_data(out_data), .done(done));

    reg [7:0] comp  [0:200000];
    reg [7:0] plain [0:200000];
    integer   errors = 0;

    task run_case;
        input [255:0] name;      // ASCII label for messages
        input integer comp_len;
        input integer plain_len;
        integer ci, pi;
        integer got_bytes;
        integer timeout;
        begin
            @(negedge clk); rst = 1'b1; in_valid = 1'b0; c_size = comp_len[31:0];
            @(negedge clk); @(negedge clk); rst = 1'b0;

            ci = 0; pi = 0; got_bytes = 0; timeout = 0;
            while (pi < plain_len && timeout < comp_len*20 + 1000) begin
                @(negedge clk);
                timeout = timeout + 1;
                // drive a compressed byte whenever the decoder is ready for one
                if (in_ready && ci < comp_len) begin
                    in_valid = 1'b1;
                    in_data  = comp[ci];
                    ci = ci + 1;
                end else begin
                    in_valid = 1'b0;
                end
                // check decompressed output as it streams out (check on the SAME edge
                // the values were driven from, i.e. after the clock the always block ran)
                #1;
                if (out_valid) begin
                    if (out_data !== plain[pi]) begin
                        $display("FAIL: %0s byte %0d = %02h exp %02h", name, pi, out_data, plain[pi]);
                        errors = errors + 1;
                    end
                    pi = pi + 1;
                    got_bytes = got_bytes + 1;
                end
            end
            in_valid = 1'b0;
            @(negedge clk);

            if (pi !== plain_len) begin
                $display("FAIL: %0s only produced %0d/%0d bytes (stalled/timed out)", name, pi, plain_len);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s decoded %0d bytes exactly", name, plain_len);
            end
        end
    endtask

    integer f, r;
    reg [8*64:1] fname;
    initial begin
        // repeats: comp=279 plain=912
        $readmemh({VDIR, "lz4_repeats_comp.hex"},  comp);
        $readmemh({VDIR, "lz4_repeats_plain.hex"}, plain);
        run_case("repeats", 279, 912);

        // random (all-literal path, LL>=15 extension exercised): comp=2009 plain=2000
        $readmemh({VDIR, "lz4_random_comp.hex"},  comp);
        $readmemh({VDIR, "lz4_random_plain.hex"}, plain);
        run_case("random", 2009, 2000);

        // fastmode (LZ4_compress_default / acceleration=1 path): comp=88 plain=1090
        $readmemh({VDIR, "lz4_fastmode_comp.hex"},  comp);
        $readmemh({VDIR, "lz4_fastmode_plain.hex"}, plain);
        run_case("fastmode", 88, 1090);

        // bars320x240 (realistic RGB565-scale test-card frame): comp=11509 plain=153600
        $readmemh({VDIR, "lz4_bars320x240_comp.hex"},  comp);
        $readmemh({VDIR, "lz4_bars320x240_plain.hex"}, plain);
        run_case("bars320x240", 11509, 153600);

        // back-to-back blits: decoder must cleanly restart on a fresh c_size/rst pulse
        // without carrying stale window/state from the previous frame.
        $readmemh({VDIR, "lz4_repeats_comp.hex"},  comp);
        $readmemh({VDIR, "lz4_repeats_plain.hex"}, plain);
        run_case("repeats_again", 279, 912);

        if (errors == 0) $display("PASS: lz4_decoder_tb");
        else begin $display("FAIL: lz4_decoder_tb (%0d errors)", errors); $fatal(1); end
        $finish;
    end
endmodule
